const crypto = require('crypto');
const secret = $env.RESEARCH_WEBHOOK_SECRET;
if (!secret) throw new Error('RESEARCH_WEBHOOK_SECRET is not configured');
const signature = $json.headers?.['x-autosfera-signature'] || '';
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body);
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (signature.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('Invalid research signature');
const job = typeof $json.body === 'string' ? JSON.parse($json.body) : $json.body;
for (const key of ['job_id','dealer_id','actor','query','trace_id','idempotency_key']) if (!job[key]) throw new Error(`Missing ${key}`);
if (job.query.length < 5 || job.query.length > 2000) throw new Error('Invalid query length');
return [{json: job}];

const crypto = require('crypto');
const job = $('Verify and Validate').item.json;
const output = $json.outputs?.[0]?.outputs?.[0]?.results?.message?.text || $json.summary || '';
if (!output) throw new Error('Langflow returned no summary');
const callback = {job_id: job.job_id, dealer_id: job.dealer_id, trace_id: job.trace_id, result: {title: `Исследование: ${job.query.slice(0, 100)}`, summary: String(output).slice(0, 30000)}, sources: Array.isArray($json.sources) && $json.sources.length ? $json.sources : [{title: 'Langflow research output', url: $env.RESEARCH_FALLBACK_SOURCE_URL}]};
if (!callback.sources[0]?.url) throw new Error('At least one source URL is required');
const raw = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', $env.RESEARCH_WEBHOOK_SECRET).update(raw).digest('hex');
return [{json: {raw, signature}}];
